-- Every matcher once passing and once failing, as compiled TypeScript calls
-- them (dot calls: the runner is @noSelf; `.not` is the field ["not"]).
local runner = require("lua_modules.reforged-test.lua.index")
local describe, it, expect = runner.describe, runner.it, runner.expect

-- Two classes as typescript-to-lua emits them (__TS__Class,
-- __TS__ClassExtends, __TS__New), Hero extending Base.
local function class(name, base)
  local c = { name = name, prototype = {} }
  c.prototype.__index = c.prototype
  c.prototype.constructor = c
  if base ~= nil then
    c.____super = base
    setmetatable(c, setmetatable({ __index = base }, base))
    setmetatable(c.prototype, base.prototype)
  end
  return c
end
local Base = class("Base")
local Hero = class("Hero", Base)
local Other = class("Other")
local function new(c, fields)
  return setmetatable(fields or {}, c.prototype)
end

describe("pass", function()
  it("toEqual", function()
    expect(3).toEqual(3)
    expect("a").toEqual("a")
    expect({ 1, { x = 2 } }).toEqual({ 1, { x = 2 } })
    expect(3)["not"].toEqual(4)
    expect({ 1 })["not"].toEqual({ 2 })
  end)
  it("toBe", function()
    local t = {}
    expect(t).toBe(t)
    expect({})["not"].toBe({})
    expect(1)["not"]["not"].toBe(1)
  end)
  it("toBeTruthy", function()
    expect(0).toBeTruthy()
    expect("").toBeTruthy()
    expect(nil)["not"].toBeTruthy()
  end)
  it("toBeFalsy", function()
    expect(false).toBeFalsy()
    expect(nil).toBeFalsy()
    expect(0)["not"].toBeFalsy()
  end)
  it("toBeUndefined", function()
    expect(nil).toBeUndefined()
    expect(false)["not"].toBeUndefined()
  end)
  it("toBeDefined", function()
    expect(0).toBeDefined()
    expect(false).toBeDefined()
    expect(nil)["not"].toBeDefined()
  end)
  it("toThrow", function()
    expect(function() error("bad thing") end).toThrow()
    expect(function() error("bad thing") end).toThrow("bad thing")
    expect(function() error({ message = "an Error object" }) end).toThrow("Error object")
    expect(function() error("a (pattern%") end).toThrow("(pattern%")
    expect(function() end)["not"].toThrow()
    expect(function() end)["not"].toThrow("bad")
    expect(function() error("bad thing") end)["not"].toThrow("good")
  end)
  it("toContainCall", function()
    Player(0)
    expect(runner.stubCalls()).toContainCall("Player(0)")
    expect(runner.stubCalls())["not"].toContainCall("Player(9)")
  end)
  it("toContain", function()
    local t = {}
    expect({ 1, t, "x" }).toContain(t)
    expect({ 1, 2 }).toContain(2)
    expect("hfoo died").toContain("died")
    expect("50%").toContain("%")
    expect({ {} })["not"].toContain({})
    expect("hfoo")["not"].toContain("died")
  end)
  it("toContainEqual", function()
    expect({ { a = 1 }, { a = 2 } }).toContainEqual({ a = 2 })
    expect({ { a = 1 } })["not"].toContainEqual({ a = 3 })
  end)
  it("toHaveLength", function()
    expect({ 1, 2, 3 }).toHaveLength(3)
    expect("abc").toHaveLength(3)
    expect({}).toHaveLength(0)
    expect("")["not"].toHaveLength(1)
  end)
  it("toMatchObject", function()
    expect({ a = 1, b = { c = 2, d = 3 }, e = 4 }).toMatchObject({ b = { c = 2 } })
    expect({ { a = 1, b = 2 }, { a = 3 } }).toMatchObject({ { a = 1 }, { a = 3 } })
    expect({ a = 1 }).toMatchObject({})
    expect({ a = 1 })["not"].toMatchObject({ a = 2 })
  end)
  it("toBeGreaterThan", function()
    expect(2).toBeGreaterThan(1)
    expect(1)["not"].toBeGreaterThan(1)
  end)
  it("toBeGreaterThanOrEqual", function()
    expect(1).toBeGreaterThanOrEqual(1)
    expect(0)["not"].toBeGreaterThanOrEqual(1)
  end)
  it("toBeLessThan", function()
    expect(1).toBeLessThan(2)
    expect(2)["not"].toBeLessThan(2)
  end)
  it("toBeLessThanOrEqual", function()
    expect(2).toBeLessThanOrEqual(2)
    expect(3)["not"].toBeLessThanOrEqual(2)
  end)
  it("toBeCloseTo", function()
    expect(0.1 + 0.2).toBeCloseTo(0.3)
    expect(0.304).toBeCloseTo(0.3)
    expect(0.3001).toBeCloseTo(0.3, 3)
    expect(math.huge).toBeCloseTo(math.huge)
    expect(0.31)["not"].toBeCloseTo(0.3)
  end)
  it("toBeInstanceOf", function()
    expect(new(Hero)).toBeInstanceOf(Hero)
    expect(new(Hero)).toBeInstanceOf(Base)
    expect(new(Base))["not"].toBeInstanceOf(Hero)
    expect({})["not"].toBeInstanceOf(Base)
    expect(5)["not"].toBeInstanceOf(Base)
  end)
  it("toMatch", function()
    expect("Footman died").toMatch("man di")
    expect("a.b")["not"].toMatch("a%.b")
    expect("a%.b").toMatch("a%.b")
  end)
  it("expect.anything", function()
    expect({ 1, "x" }).toEqual({ expect.anything(), "x" })
    expect(false).toEqual(expect.anything())
    expect({ a = { 1 } }).toMatchObject({ a = expect.anything() })
    expect({ { "x", 60 } }).toContainEqual({ expect.anything(), 60 })
  end)
  it("expect.any", function()
    expect({ 1, "x", true, {}, print }).toEqual({
      expect.any("number"),
      expect.any("string"),
      expect.any("boolean"),
      expect.any("table"),
      expect.any("function"),
    })
    expect({ hero = new(Hero) }).toMatchObject({ hero = expect.any(Base) })
    expect({ new(Base) }).toContainEqual(expect.any(Base))
    expect(1)["not"].toEqual(expect.any("string"))
  end)
  it("expect.objectContaining", function()
    expect({ id = 1, unit = { name = "hfoo", hp = 420 } }).toEqual({
      id = 1,
      unit = expect.objectContaining({ name = "hfoo" }),
    })
    expect({ a = 1, b = 2 }).toEqual(expect.objectContaining({ b = 2 }))
    expect({ { a = 1, b = 2 } }).toContainEqual(expect.objectContaining({ a = 1 }))
    expect({ a = { b = expect.stringContaining("world") } }).toEqual({
      a = expect.objectContaining({ b = expect.objectContaining({}) }),
    })
  end)
  it("expect.arrayContaining", function()
    expect({ 3, 1, 2 }).toEqual(expect.arrayContaining({ 1, 3 }))
    expect({ list = { { a = 1 }, { a = 2 } } }).toMatchObject({
      list = expect.arrayContaining({ { a = 2 } }),
    })
    expect({ { 1, 2 } }).toContainEqual(expect.arrayContaining({ 2 }))
  end)
  it("expect.stringContaining", function()
    expect({ "hfoo died" }).toEqual({ expect.stringContaining("died") })
    expect({ msg = "100% done" }).toMatchObject({ msg = expect.stringContaining("%") })
    expect({ "a", "hello world" }).toContainEqual(expect.stringContaining("world"))
  end)
end)

