describe("raise", function()
  it("expect.any of nil", function()
    -- What expect.any(Number) compiles to: Number is nil in Lua.
    expect.any(nil)
  end)
  it("expect.any of an unknown type name", function()
    expect.any("integer")
  end)
  it("toBeInstanceOf of nil", function()
    expect({}).toBeInstanceOf(nil)
  end)
end)
